# connected zero components on demo, which initial seeds touch; output target matches which?
from collections import deque
R,C=21,18
visited=set(); comps=[]
for r in range(R):
 for c in range(C):
  if di[r][c]==0 and (r,c) not in visited:
   q=deque([(r,c)]);visited.add((r,c)); comp={(r,c)}
   while q:
    x,y=q.popleft()
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     z,w=x+dx,y+dy
     if 0<=z<R and 0<=w<C and di[z][w]==0 and (z,w) not in visited:
      visited.add((z,w));comp.add((z,w));q.append((z,w))
   comps.append(comp)
