# template object coordinates for each input non-background color. test zero placements translations, D4
import numpy as np
for name,inp,out,R,C,color in [('d1',di,do,21,18,7),('d2',d2i,d2o,18,24,8),('d3',d3i,d3o,19,24,8)]:
 coords=[(r,c) for r in range(R) for c in range(C) if inp[r][c]==color]
 # components are marker all cells; maybe use all as template
 delta={(r-min(x for x,y in coords),c-min(y for x,y in coords)) for r,c in coords}
 trans=[]
 for flip in (1,-1):
  for k in range(4):
   pts=[]
   for r,c in delta:
    x,y=r,flip*c
    for _ in range(k): x,y=y,-x
    pts.append((x,y))
   mr=min(x for x,y in pts);mc=min(y for x,y in pts)
   trans.append({(x-mr,y-mc) for x,y in pts})
 occ=set()
 for shape in trans:
  h=max(r for r,c in shape)+1;w=max(c for r,c in shape)+1
  for r0 in range(R-h+1):
   for c0 in range(C-w+1):
    cells={(r0+r,c0+c) for r,c in shape}
    if all(inp[r][c]==0 for r,c in cells): occ|=cells
 actual={(r,c) for r in range(R) for c in range(C) if inp[r][c]==0 and out[r][c]==color}
 print(name,'template size',len(coords),'actual',len(actual),'occ',len(occ),'miss',len(actual-occ),'extra',len(occ-actual))

